/* Nondeployed concept adapter. Reuses the mounted reader; no learning store. */
(()=>{'use strict';
const data=window.GLP_ROOM_CONTENT,frame=document.getElementById('existing-reader'),dialog=document.getElementById('room'),content=document.getElementById('room-content');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>'<a href="'+escape(url)+'" target="_blank" rel="noopener noreferrer">'+escape(label)+'</a>';
let savedAnchor=null,opener=null,clock=null,breathOptedIn=false;
function remember(){const d=frame.contentDocument,w=frame.contentWindow;if(!d)return;const play=d.querySelector('#play');if(play?.getAttribute('aria-pressed')==='true')play.click();const line=Array.from(d.querySelectorAll('.scripture-line')).find(e=>e.getBoundingClientRect().bottom>48);savedAnchor={node:line,top:line?.getBoundingClientRect().top,y:w.scrollY};}
function open(kind,button){remember();opener=button;frame.inert=true;dialog.showModal();if(kind==='simran')simran();else arrival();}
dialog.addEventListener('close',()=>{clearInterval(clock);frame.inert=false;const w=frame.contentWindow;if(savedAnchor){const offset=savedAnchor.node?.getBoundingClientRect().top;w.scrollTo({top:offset===undefined?savedAnchor.y:w.scrollY+offset-savedAnchor.top,behavior:'instant'});}opener?.focus({preventScroll:true});document.getElementById('return-status').textContent='Returned to the same reading place. The visual guide is paused.';});
document.getElementById('return-reader').onclick=()=>dialog.close();
document.getElementById('simran-open').onclick=e=>open('simran',e.currentTarget);
document.getElementById('arrival-open').onclick=e=>open('arrival',e.currentTarget);
function focusTitle(){content.querySelector('h1')?.focus({preventScroll:true});dialog.scrollTop=0;}
function simran(){clearInterval(clock);breathOptedIn=false;document.getElementById('room-kicker').textContent='Simran Room · concept';content.innerHTML='<h1 id="room-title" tabindex="-1">Room for quiet attention</h1><p class="intro">Silence, with room to choose. Return to your reading at any time.</p><nav class="room-modes" aria-label="Simran Room views">'+['Arrive','Breath attention','Naam Simran','Stillness','Learn'].map((name,i)=>'<button data-view="'+i+'" aria-pressed="'+(i===0)+'">'+name+'</button>').join('')+'</nav><section id="simran-panel" aria-label="Selected room view"></section><p class="review-note">Unpublished design prototype. Guidance and interpretations await qualified Sikh review. There is no recorded or synthetic voice.</p>';content.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(Number(b.dataset.view)));view(0,false);focusTitle();}
function view(index,focus=true){content.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.view)===index));const panel=document.getElementById('simran-panel');const views=[
'<h2 tabindex="-1">Arrive</h2><p>You can stay here, choose another view, or return to Gurbani.</p><p class="note">No session length, sequence or completion is required.</p>',
'<h2 tabindex="-1">Breath attention · optional</h2><p>This interface experiment is optional. It is not presented as a Sikh practice prescription.</p><button id="breath-choice" aria-pressed="'+breathOptedIn+'">'+(breathOptedIn?'Hide attention cue':'Show a gentle attention cue')+'</button><p id="breath-cue" '+(breathOptedIn?'':'hidden')+'>If comfortable, notice your natural breath. There is no pace to follow. You can skip this at any time.</p>',
'<h2 tabindex="-1">Naam Simran</h2><p>A quiet space. No recitation is played.</p><p class="note">Practice instructions are withheld while qualified review is pending. Learn contains the source passages and their context links.</p>',
'<h2 tabindex="-1">Stillness</h2><p>Nothing to complete here.</p><p class="note">This is an interface choice, not a claim about spiritual attainment.</p>',
'<h2 tabindex="-1">Learn · source first</h2><p class="note">Original Gurbani · Japji Sahib · Sri Guru Granth Sahib, Ang 2. These passages are not instructions for the optional breath interface.</p>'+data.anchors.map(a=>'<p class="scripture" lang="pa" data-source-id="'+a.id+'">'+escape(a.text)+'</p><p class="source">'+escape(a.unit)+' · Ang '+a.ang+'<br>'+link(a.sourceUrl,'Read the source in context')+'</p>').join('')+'<h3>Interpretation and practical guidance</h3><p>Withheld in this prototype pending qualified review.</p><h3>Sikh Rehat Maryada · orientation</h3><p class="note">Articles III–IV discuss personal spiritual life, Naam and Gurbani. Their inclusion does not establish an app-specific breathing method.</p><p class="source">'+link('https://sgpc.net/sikh-rehat-maryada-in-english/','SGPC source index')+' · '+link('https://fremontgurdwara.org/sikh-rehat-maryada/','Read the gurdwara’s HTML reproduction')+'</p>'
];panel.className=index===4?'':'quiet-panel';panel.innerHTML=views[index];if(index===1)document.getElementById('breath-choice').onclick=()=>{breathOptedIn=!breathOptedIn;const b=document.getElementById('breath-choice');b.setAttribute('aria-pressed',breathOptedIn);b.textContent=breathOptedIn?'Hide attention cue':'Show a gentle attention cue';document.getElementById('breath-cue').hidden=!breathOptedIn;};if(focus)panel.querySelector('h2').focus({preventScroll:true});}
function arrival(){document.getElementById('room-kicker').textContent='Gurdwara Arrival · concept';content.innerHTML='<h1 id="room-title" tabindex="-1">A quiet arrival</h1><p class="intro">Choose a place. Opening its official broadcaster is always a separate action.</p><div class="place-picker"><label for="place">Gurdwara</label><select id="place">'+data.places.map(p=>'<option value="'+p.id+'">'+escape(p.name)+'</option>').join('')+'</select></div><section id="place-detail" aria-label="Selected gurdwara"></section><p class="review-note">Unpublished design prototype. Typography is used while photograph rights and remaining Gurmukhi place names await verification.</p>';document.getElementById('place').onchange=e=>place(e.target.value);place(data.places[0].id);focusTitle();}
function place(id){clearInterval(clock);const p=data.places.find(v=>v.id===id),host=document.getElementById('place-detail');host.innerHTML='<div class="place-intro" id="arrival-intro">'+(p.gurmukhi?'<p class="place-gurmukhi" lang="pa">'+escape(p.gurmukhi)+'</p>':'')+'<h2>'+escape(p.name)+'</h2><p>'+escape(p.location)+'</p><p class="local-clock"><time id="local-time"></time><br><span class="note">Local time · '+escape(p.timeZone)+'</span></p><p class="note">The clock does not indicate services or broadcast status.</p></div><div class="arrival-actions"><button id="enter-place" class="primary" aria-expanded="false" aria-controls="place-info">Enter</button><button id="skip-arrival">Skip arrival</button></div><section id="place-info" hidden><h3 tabindex="-1">About this place</h3><address>'+escape(p.address)+'</address><p>'+escape(p.intro)+'</p><p class="source">'+link(p.introSource,'Official introduction')+'</p><p><a class="outbound" href="'+escape(p.officialUrl)+'" target="_blank" rel="noopener noreferrer">'+escape(p.officialLabel)+' ↗</a></p><p class="note">'+escape(p.routeNote)+'</p></section>';function tick(){const t=document.getElementById('local-time');if(t){const now=new Date();t.dateTime=now.toISOString();t.textContent=new Intl.DateTimeFormat('en',{timeZone:p.timeZone,hour:'numeric',minute:'2-digit',weekday:'short',month:'short',day:'numeric'}).format(now);}}tick();clock=setInterval(tick,30000);const enter=()=>{document.getElementById('arrival-intro').classList.add('no-fade');document.getElementById('place-info').hidden=false;document.getElementById('enter-place').setAttribute('aria-expanded','true');document.querySelector('#place-info h3').focus();};document.getElementById('enter-place').onclick=enter;document.getElementById('skip-arrival').onclick=enter;}
})();
